def _expect_str_or_none(value: object, label: str) -> str | None:
    if value is None or isinstance(value, str):
        return value
    raise ValueError(f"{label} must be a string or null")


def _expect_rel_path(value: object, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{label} must be a non-empty string")
    if "\\" in value:
        raise ValueError(f"{label} must use forward slashes: {value!r}")
    if value.startswith("/") or value.endswith("/"):
        raise ValueError(f"{label} must be a clean relative path: {value!r}")
